class Solution:
    def findErrorNums(self, nums: list[int]) -> list[int]:
        n = len(nums)
        count = [0] * (n + 1)              # index v counts value v, values are 1..n
        for v in nums:                     # one pass: O(n)
            count[v] += 1
        dup = missing = 0
        for v in range(1, n + 1):          # second pass over the value range
            if count[v] == 2:
                dup = v
            elif count[v] == 0:
                missing = v
        return [dup, missing]
